// Mailchimp on an API key: every operation of the Marketing API (audiences, contacts, campaigns, automations, reports,
// stores...). actions.json is generated by `bun scripts/openapi-actions.ts mailchimp`; an audience's events start
// automations by webhook (triggers.ts). The key ends in its data centre (-us21), which is the API's host.
import { createHash } from "node:crypto";
import { AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const HELP = "Mailchimp → your profile → Extras → API keys → Create A Key";

// the data centre at the end of the key; anything else would send the key to some other host
export const dataCentre = (key: string) => {
  const dc = key.split("-").pop() ?? "";
  if (!key.includes("-") || !/^[a-z]{2,4}\d{1,3}$/.test(dc)) throw new AppsError(`that isn't a Mailchimp API key: it should end in its data centre, like -us21 (${HELP})`);
  return dc;
};

export const api: Api = {
  name: "Mailchimp",
  base: "https://server.api.mailchimp.com/3.0",
  tokenHelp: HELP,
  auth: (key) => ({ Authorization: `Basic ${Buffer.from(`emplio:${key}`).toString("base64")}` }),
  url: (key, base, path) => `${base.replace("//server.", `//${dataCentre(key)}.`)}${path}`,
};

// a contact is named by the MD5 of its lower-case email; an email given instead is hashed here
// (no spread: it would build every input schema up front)
const byEmail = (action: OwnAction): OwnAction => ({
  description: action.description,
  readOnly: action.readOnly,
  get input() {
    return action.input;
  },
  run: (input: Record<string, unknown>, key: string) => {
    const s = input.subscriber_hash;
    const hashed = typeof s === "string" && s.includes("@") ? createHash("md5").update(s.trim().toLowerCase()).digest("hex") : s;
    return action.run({ ...input, ...(s !== undefined && { subscriber_hash: hashed }) }, key);
  },
});
const actions = Object.fromEntries(Object.entries(await specActions(new URL("./actions.json", import.meta.url), api)).map(([n, a]) => [n, byEmail(a)]));

export const mailchimp: OwnApp = {
  app: "mailchimp",
  name: "Mailchimp",
  logo: "/logos/mailchimp.svg",
  keyField: {
    label: "API key",
    help: "In Mailchimp open your profile → Extras → API keys → Create A Key, name it Emplio, then copy the key (it ends in something like -us21). Emplio can then do whatever your Mailchimp account can.",
    placeholder: "your key, ending in -us21",
  },
  async check(key) {
    const me = (await call(api, key, { method: "GET", path: "/", query: ["fields"], headers: [] }, { fields: "account_name,email" })) as { account_name?: string; email?: string };
    return me.account_name || me.email;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event, config) => watch(api, key, connection, event, config),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery) => receive(delivery),
    wanted,
  },
  actions,
};
